+ * @param {ArrayLike<unknown>} items source collection; never mutated.
+ * @param {number} page one-based page number.
+ * @param {number} pageSize number of items per page.
+ * @returns {{items: Array<unknown>, total: number, pageCount: number}} a new array
+ *   holding a shallow copy of the requested slice. Pages past the end yield an
+ *   empty `items` array; an empty collection yields `pageCount === 0`.
+ * @throws {RangeError} if `page` or `pageSize` is not a positive integer.
+ */
+export function paginate(items, page, pageSize) {
+  const currentPage = requirePositiveInteger(page, 'page');
+  const currentPageSize = requirePositiveInteger(pageSize, 'pageSize');
+
+  if (items === null || items === undefined) {
+    throw new TypeError('items must be a list or array-like value');
+  }
+
+  const start = (currentPage - 1) * currentPageSize;
+  return {
+    // slice() copies, so callers may mutate the result without touching the input.
+    items: Array.prototype.slice.call(items, start, start + currentPageSize),
+    total: items.length,
+    pageCount: Math.ceil(items.length / currentPageSize),
+  };
