+// Shared safety policy for key paths used by read-key.mjs and write-key.mjs.
+// A key must be a non-empty relative path that never escapes its root.
+
+export function isSafeKey(value) {
+  return typeof value === 'string' && !!value && !value.startsWith('/') && !value.split('/').includes('..');
+}
+
+export function assertSafeKey(value) {
+  if (!isSafeKey(value)) throw new TypeError('unsafe key');
+  return value;
+}
